var probeSiteOrigin = func(ctx context.Context, domain string) siteProbeResult {
  req, _ := http.NewRequestWithContext(cctx, http.MethodGet, "https://"+domain+"/", nil)
  req.Header.Set("User-Agent", "agentchassis-discovery/1.0 (+site_unreachable)")
  resp, err := (&http.Client{Timeout: siteProbeTimeout}).Do(req)
  if err != nil { return siteProbeResult{TransportErr: err.Error()} }
  body, _ := io.ReadAll(io.LimitReader(resp.Body, siteProbeBodyCap))
  return siteProbeResult{Status: resp.StatusCode, FinalHost: resp.Request.URL.Host, Body: body}
}

